shader_type canvas_item;

uniform vec4 tint_color : source_color = vec4(1.0, 0.0, 0.0, 1.0);
uniform float intensity : hint_range(0.0, 1.0) = 0.0;

void fragment() {
	COLOR.rgb = mix(COLOR.rgb, tint_color.rgb, intensity);

@onready var player: Player = get_parent()
@onready var material: ShaderMaterial = player.get_node("Sprite2D").material


func _process(_delta: float) -> void:
	var t := 0.0
	# fail() freezes `invulnerable` without clearing it, so failing and cleared both force 0.0 (R8, F4).
	if player.invulnerable > 0.0 and not player.is_failing and not player.is_cleared:
		t = player.invulnerable / Tuning.INVULNERABLE_TIME
	material.set_shader_parameter("intensity", t)

shader_type spatial;
render_mode unshaded;

uniform sampler2D source_color_tex : source_color, filter_nearest;
uniform sampler2D raw_data_tex : filter_nearest;

uniform bool use_source_color = true;

void fragment() {
	if (use_source_color) {
		ALBEDO = texture(source_color_tex, UV).rgb;
	} else {
		ALBEDO = texture(raw_data_tex, UV).rgb;
	}

group_uniforms textures;
uniform sampler2D texture_albedo : source_color, filter_linear_mipmap;
uniform sampler2D texture_normal : hint_normal, filter_linear_mipmap;
uniform sampler2D texture_roughness : hint_default_white, filter_linear_mipmap;
group_uniforms;

// 3. 结霜遮罩计算（粗糙度低的地方先结霜，柔和过渡）
// 过渡半带宽设为 0.1（总过渡带宽度 0.2）。
// 门槛 threshold 在 frost_amount 从 0 到 1 时，由 -0.1 线性扩展到 1.1：
float threshold = mix(-0.1, 1.1, frost_amount);
// 粗糙度低于 threshold 时结霜越充分，因此用 (threshold - rough_tex) 映射到 [-0.1, 0.1]
float frost_mask = smoothstep(-0.1, 0.1, threshold - rough_tex);

// --- 表面组 ---
group_uniforms surface;
uniform vec4 base_tint : source_color = vec4(1.0, 1.0, 1.0, 1.0);
uniform float normal_scale : hint_range(0.0, 2.0, 0.05) = 1.0;
uniform float roughness_scale : hint_range(0.0, 2.0, 0.05) = 1.0;

// --- 结霜组 ---
group_uniforms frost;
uniform vec4 frost_color : source_color = vec4(0.85, 0.92, 1.0, 1.0);
uniform float frost_amount : hint_range(0.0, 1.0, 0.01) = 0.0;

